class Solution {
    public String bestHand(int[] ranks,char[] suits){
        boolean flush=true;
        for(char suit:suits)flush&=suit==suits[0];
        if(flush)return "Flush";
        int[] frequency=new int[14];
        int maximum=0;
        for(int rank:ranks)maximum=Math.max(maximum,++frequency[rank]);
        if(maximum>=3)return "Three of a Kind";
        if(maximum>=2)return "Pair";
        return "High Card";
    }
}

code.kotlin:
class Solution {
    fun bestHand(ranks:IntArray,suits:CharArray):String{
        if(suits.all{
            it==suits[0]
        })return "Flush";
        val frequency=IntArray(14);
        var maximum=0;
        for(rank in ranks)maximum=maxOf(maximum,++frequency[rank]);
        return when{
            maximum>=3->"Three of a Kind";
            maximum>=2->"Pair";
            else->"High Card"
        }
    }
}

